<?php $e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); ?><style>
.joki-toolbar{display:grid;grid-template-columns:minmax(0,1fr) 220px;align-items:end;gap:12px;margin-bottom:18px}.joki-toolbar .search{max-width:none}.joki-filter-field{display:grid;gap:6px;color:var(--muted);font-size:12px;font-weight:700}.joki-filter-field select{width:100%;height:43px}.joki-panel .panel-head{padding:22px 24px}.joki-panel table{min-width:820px}.joki-panel th{white-space:nowrap}.joki-panel td{padding-top:18px;padding-bottom:18px;vertical-align:middle}.joki-panel td:first-child strong{font-family:'Space Grotesk',sans-serif;font-size:15px}.joki-panel .status{font-size:12px;font-weight:700}.joki-actions{display:flex;align-items:center;gap:7px}.joki-actions form{display:inline}.joki-actions .btn{min-width:36px}.modal-panel{display:none;position:fixed;inset:0;z-index:20;overflow-y:auto;background:rgba(23,35,46,.5);padding:7vh 16px 30px}.modal-panel.open{display:block}.modal-panel .modal-box{width:min(500px,100%);max-height:86vh;overflow-y:auto;margin:auto;padding:0 26px 26px;background:#fff;border:1px solid rgba(220,229,233,.9);border-radius:12px;box-shadow:0 20px 60px rgba(23,35,46,.2)}.modal-panel .panel-head{position:sticky;top:0;margin:0 -26px 22px;padding:20px 26px 16px;background:#fff;border-bottom:1px solid var(--line);z-index:1}.modal-panel form{display:grid;gap:14px}.modal-panel label{display:block;margin-bottom:6px;font-weight:600}.modal-panel input,.modal-panel select{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font:inherit}.modal-panel input:focus,.modal-panel select:focus{outline:0;border-color:var(--teal);box-shadow:0 0 0 3px rgba(0,124,131,.1)}.modal-close{border:0;background:transparent;font-size:24px;color:var(--muted);cursor:pointer}.modal-close:hover{color:var(--ink)}
@media(max-width:650px){.joki-toolbar{grid-template-columns:1fr;align-items:stretch}.joki-filter-field select{width:100%}.joki-panel .panel-head{padding:18px}.joki-panel td{padding-top:14px;padding-bottom:14px}.modal-panel{padding:18px 10px}.modal-panel .modal-box{max-height:calc(100vh - 36px);padding:0 18px 20px}.modal-panel .panel-head{margin:0 -18px 18px;padding:17px 18px 14px}}
</style>
<div class="toolbar joki-toolbar">
  <form class="search" method="get">
    <input type="hidden" name="tab" value="joki">
