  <?php foreach ($jokiRows as $joki): ?><tr><td><strong><?= $e($joki['nama']) ?></strong></td><td><?= $e($joki['whatsapp']) ?></td><td><?= $e($joki['keahlian']) ?></td><td><span class="status <?= $joki['status'] === 'aktif' ? 'selesai' : 'cancelled' ?>"><?= $e(ucfirst($joki['status'])) ?></span></td><td><?= number_format((float) $joki['rating'], 1) ?>/5</td><td><?= (int) $joki['total_selesai'] ?></td><td><strong><?= formatRupiah($joki['saldo_joki']) ?></strong></td><td><div class="joki-actions"><button class="btn small" data-modal="joki-edit-<?= (int) $joki['id'] ?>" title="Edit joki"><i class="fa-solid fa-pen"></i></button><form method="post"><input type="hidden" name="action" value="toggle_joki"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><input type="hidden" name="joki_id" value="<?= (int) $joki['id'] ?>"><button class="btn small light" title="Ubah status"><i class="fa-solid fa-power-off"></i></button></form></div></td></tr><?php endforeach; ?>
