<script>document.querySelectorAll('[data-modal]').forEach(function(button){button.addEventListener('click',function(){var modal=document.getElementById(button.dataset.modal);modal.classList.add('open');modal.querySelector('input:not([type="hidden"])').focus();});});document.querySelectorAll('[data-close-modal]').forEach(function(button){button.addEventListener('click',function(){button.closest('.modal-panel').classList.remove('open');});});document.querySelectorAll('.modal-panel').forEach(function(modal){modal.addEventListener('click',function(event){if(event.target===modal)modal.classList.remove('open');});});document.addEventListener('keydown',function(event){if(event.key==='Escape')document.querySelectorAll('.modal-panel.open').forEach(function(modal){modal.classList.remove('open');});});</script>
